  ('prod_beb_gin', 'Gin Tonic Heráclito', 'Gin nacional premium, agua tónica, bayas de enebro y rodaja de limón.', 4800, 'Bebidas sin alcohol', 'Tragos / Destilados', 'bebida', 15, false, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', NULL, '[]'::jsonb, NULL),
  ('prod_beb_whisky', 'Whisky Macallan 12 Años (Medida)', 'Medida selecta de whisky Single Malt escocés servido en copa clásica.', 7500, 'Bebidas sin alcohol', 'Tragos / Destilados', 'bebida', 15, false, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', NULL, '[]'::jsonb, NULL),
  ('prod_cafe_espresso', 'Café Espresso Doble', 'Intenso café espresso de grano de especialidad colombiano.', 2400, 'Bebidas sin Alcohol', 'Cafetería', 'bebida', 15, false, true, 'https://images.unsplash.com/photo-1509042239860-f550ce710b93?w=400&q=80', NULL, NULL, '[]'::jsonb, NULL),
  ('prod_car_bondiola_ahumada', 'Bondiola ahumada', 'Bondiola de cerdo tiernizada y ahumada con leña de manzano, servida con puré de batata dulce.', 18500, 'Cortes a la Parrilla', NULL, 'plato', 15, true, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', NULL, '[]'::jsonb, NULL),
  ('prod_car_lomo_pimienta', 'Lomo en demiglace de pimienta', 'Medallón de lomo vacuno grillado con reducción de salsa demiglace a la pimienta negra y guarnición.', 23800, 'Cortes a la Parrilla', NULL, 'plato', 20, true, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', NULL, '[]'::jsonb, NULL),
  ('prod_car_mila_entrecot', 'Milanesa de entrecot con fideos', 'Corte de entrecot tierno en milanesa dorada y crujiente, acompañado de fideos al pesto o manteca.', 16500, 'Cortes a la Parrilla', NULL, 'plato', 18, true, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', NULL, '[]'::jsonb, NULL),
  ('prod_car_ojo_bife', 'Ojo de bife con aligot de papas', 'Corte premium de ojo de bife grillado a las brasas, acompañado de aligot cremoso de papas con queso fundido.', 24500, 'Cortes a la Parrilla', NULL, 'plato', 20, true, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', '["Marcar el ojo de bife a la parrilla sobre brasas de leña fuerte para sellar.","Cocinar al punto solicitado por el cliente (Jugoso: 52°C interno; A punto: 57°C; Cocido: 63°C).","En cazo aparte, calentar el puré de papa andina con manteca y crema. Incorporar el queso fontina y mozzarella rallados.","Trabajar vigorosamente el puré en caliente con cuchara de madera hasta lograr la textura elástica (hilo del aligot)."]'::jsonb, '["Lácteos"]'::jsonb, 'Servir la carne trinchada de lado y verter el aligot caliente al momento frente al cliente en plato rústico.'),
  ('prod_coca_cola_original', 'Coca-Cola Sabor Original (Lata)', 'Lata de Coca-Cola original de 354ml bien helada.', 2500, 'Bebidas sin Alcohol', 'Gaseosas', 'bebida', 15, false, true, 'data:image/jpeg;base64,', NULL, NULL, '[]'::jsonb, NULL),
  ('prod_coca_cola_zero', 'Coca-Cola Sin Azúcar (Lata)', 'Lata de Coca-Cola Sin Azúcar de 354ml bien helada.', 2500, 'Bebidas sin alcohol', 'Gaseosas', 'bebida', 15, false, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', NULL, '[]'::jsonb, NULL),
  ('prod_cri_humita', 'Humita en chala norteña', 'Clásica humita elaborada con choclo fresco rallado, queso derretido, albahaca y envuelta en chala.', 9500, 'Comidas Criollas', NULL, 'plato', 10, true, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', NULL, '[]'::jsonb, NULL),
  ('prod_cri_lentejas', 'Guiso de lentejas tradicional', 'Lentejas guisadas a fuego lento con chorizo colorado, panceta, carne vacuna y vegetales frescos.', 10800, 'Comidas Criollas', NULL, 'plato', 10, true, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', NULL, '[]'::jsonb, NULL),
  ('prod_cri_locro', 'Locro tradicional', 'Maíz blanco, porotos, patitas de cerdo, chorizo colorado y falda, servido con su salsa picante de verdeo.', 11500, 'Comidas Criollas', NULL, 'plato', 8, true, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', NULL, '[]'::jsonb, NULL),
  ('prod_ent_carpaccio', 'Carpaccio de lomo curado', 'Finas láminas de lomo vacuno curado, acompañadas de rúcula fresca, lascas de queso parmesano y vinagreta de limón.', 8500, 'Entradas Criollas', NULL, 'plato', 5, true, true, 'data:image/jpeg;base64,', 'data:image/jpeg;base64,', '["Cortar el lomo curado en láminas ultrafinas con la cortadora de fiambres fría.","Disponer las láminas en forma de abanico en el plato frío sin encimarlas demasiado.","Distribuir homogéneamente las alcaparras escurridas y las lascas de queso parmesano.","Terminar rociando con el hilo de aceite de oliva trufado en forma de espiral."]'::jsonb, '["Lácteos"]'::jsonb, 'Servir en plato plano negro pre-enfriado para resaltar el color de la carne curada.')
ON CONFLICT (id_producto) DO UPDATE SET
  nombre = EXCLUDED.nombre,
  descripcion = EXCLUDED.descripcion,
  precio_venta = EXCLUDED.precio_venta,
  categoria = EXCLUDED.categoria,
  subcategoria = EXCLUDED.subcategoria,
  tipo = EXCLUDED.tipo,
  tiempo_preparacion_estimado = EXCLUDED.tiempo_preparacion_estimado,
  requiere_cocina = EXCLUDED.requiere_cocina,
  activo = true,
  imagen = EXCLUDED.imagen,
  url_imagen = EXCLUDED.url_imagen,
  pasos_preparacion = EXCLUDED.pasos_preparacion,
  alergenos = EXCLUDED.alergenos,
  consejo_emplatado = EXCLUDED.consejo_emplatado,
  updated_at = NOW();
